            var c = GD.vctrl, p = null, ok = false;
            try { p = c && c.rareAt ? c.rareAt() : null; ok = !!(p && p.id === id) || !!(c && c._summon && c._summon(id)); } catch (e) { ok = false; }
            if (!ok) { setTimeout(tryIt, 250); return; }
