        var w = gdViewWorld(), o = gdViewOpts(gdState(w));
        MogiSound.play({ world: w, season: o.season, light: o.light, stage: skyStage(w, o.stage), event: o.event, weather: o.weather, fireworks: o.fireworks, sky: gdSkyOpen(), date: o.date });
