            if (/^[〜～]/.test(w.reading || '') && '〜' + e.reading === w.reading) e.reading = w.reading;   // saved before 〜 readings kept their 〜 (のすえ → 〜のすえ); a reading the user changed stays
            if (!w.furigana && e.furigana && toHiragana(e.reading || '') === toHiragana(w.reading || '')) e.furigana = '';   // placed again with the current furigana rules (the deck's reading, unchanged by the user)
