        var cards = [];
        words.forEach(function(e) { cards.push({ e: e, side: 'L' }); cards.push({ e: e, side: 'R' }); });
        shuffleInPlace(cards);
        wq.cards = cards; wq.open = []; wq.found = 0; wq.lock = true;
        var body = document.querySelector('#flash-view .flash-body');
        document.querySelector('#flash-view .flash-progress').textContent = wq.ta ? '第' + (wq.board + 1) + '面' : '';
        var face = function(c) {
            if (c.side === 'L') return '<span class="mem-w">' + escapeHtml(c.e.word) + '</span>';
            return o.side === 'reading' ? '<span class="mem-r">' + escapeHtml(toHiragana(c.e.reading)) + '</span>' : '<span class="mem-m">' + escapeHtml(wqClip(wqMeaning(c.e), 40)) + '</span>';
        };
